{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    required = set(case.get("required_symbols", []))
    by_id = {node["id"]: node for node in nodes}
    children = {}
    for node in nodes:
        children.setdefault(node.get("parent"), []).append(node["id"])

    selected = set()
    for symbol in required:
        candidates = [node for node in nodes if node.get("symbol") == symbol]
        if candidates:
            best = max(candidates, key=lambda node: node.get("utility", 0))
            selected.add(best["id"])

    retained = {node["id"] for node in nodes if not node.get("removable", False)}
    retained.update(selected)

    for node_id in tuple(selected):
        current = by_id.get(node_id)
        seen = set()
        while current is not None:
            parent_id = current.get("parent")
            if parent_id is None or parent_id in seen:
                break
            seen.add(parent_id)
            retained.add(parent_id)
            current = by_id.get(parent_id)

    return {
        "removed_node_ids": [node["id"] for node in nodes if node.get("removable", False) and node["id"] not in retained],
        "retained_node_ids": [node["id"] for node in nodes if node["id"] in retained]
    }"}
